android.extraProguardRules:
# views made by Expo modules are built by reflection; without this the release build strips their constructors and the app closes when one is shown (the 3D figure)
-keepclassmembers class * extends android.view.View { public <init>(android.content.Context, expo.modules.kotlin.AppContext); }
-keep class expo.modules.gl.** { *; }
